// The defects register (docs/defects.toml) is checked and its page generated by scripts/defects.mjs, at each
// commit and in CI: these tests make sure the checker refuses what it must.
import { test } from "node:test";
import assert from "node:assert/strict";
import { parse } from "smol-toml";
import { checkDefect } from "../scripts/defects.mjs";

const ENTRY = `id = "DEF-001"
date = 2026-10-22
titre = "A defect"
type = "code"
etiquettes = ["page"]
gravite = "minor"
statut = "fixed"
constat = "c"
cause = "c"
solution = "s"
resultat = "r"
preuve = ["Rule: stated"]`;
const entry = (extra = "") => parse(`${ENTRY}\n${extra}`);
const features = new Set(["MAINT-03"]);

test("MAINT-03 a complete entry passes", () => {
  assert.deepEqual(checkDefect(entry('liens = ["MAINT-03", "62420b2"]'), 1, null, features), []);
});

test("MAINT-03 the checker refuses a gap, an unknown value, a missing proof file and a bad link", () => {
  const problems = (defect, number = 1) => checkDefect(defect, number, null, features).join("\n");
  assert.match(problems(entry(), 2), /identifier expected DEF-002/);
  assert.match(problems({ ...entry(), etiquettes: ["nonsense"] }), /tag "nonsense" unknown/);
  assert.match(problems({ ...entry(), preuve: ["tests/missing.test.js"] }), /file not found/);
  assert.match(problems({ ...entry(), preuve: ["tests/data.test.js"] }), /does not name it/);
  assert.match(problems(entry('liens = ["NOPE-01"]')), /no commit, no feature/);
  const { cause, ...incomplete } = entry();
  assert.ok(cause);
  assert.match(problems(incomplete), /field "cause" missing/);
});

test("MAINT-03 DEF-019 a list field given as text is refused, not read letter by letter", () => {
  const problems = checkDefect({ ...entry(), preuve: "Rule: stated", etiquettes: "page" }, 1, null, features);
  assert.deepEqual(problems, ["DEF-001: etiquettes: not a list", "DEF-001: preuve: not a list"]);
});
